 proof fn always_double_equality<T>(p: TempPred<T>)
     ensures always(always(p)) == always(p),
 {
+    // Unfold `always` twice; both sides quantify the same condition
+    // over all natural numbers, so they define extensionally equal predicates.
+    assert(always(always(p)).entails(always(p)));
